package io.github.iamthecodedecoded.tickclock;

import java.awt.*;
import javax.swing.*;

/** Visual probe. Uses the production JAR's renderer with explicitly simulated ticks. */
public final class ClockPreview extends JPanel
{
    private final TickPhase phase = new TickPhase();

    private ClockPreview()
    {
        setBackground(new Color(27, 31, 35));
        setPreferredSize(new Dimension(620, 340));
        phase.tick(System.nanoTime());
        new Timer(600, e -> phase.tick(System.nanoTime())).start();
        new Timer(16, e -> repaint()).start();
    }

    @Override protected void paintComponent(Graphics graphics)
    {
        super.paintComponent(graphics);
        Graphics2D g = (Graphics2D) graphics.create();
        g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
        g.setColor(new Color(232, 235, 239));
        g.setFont(new Font("SansSerif", Font.BOLD, 19));
        g.drawString("Tick Clock", 28, 36);
        g.setFont(new Font("SansSerif", Font.PLAIN, 13));
        g.setColor(new Color(164, 175, 185));
        g.drawString("Production renderer / simulated 600 ms ticks", 28, 61);
        double p = phase.progress(System.nanoTime());
        draw(g, 36, 102, 36, p, false);
        draw(g, 132, 82, 80, p, false);
        g.drawString("Actual size", 28, 186);
        g.drawString("Enlarged", 143, 186);
        g.drawString("Clockwise fill: 0%    >    25%    >    50%    >    75%    >    100%", 28, 222);
        for (int i = 0; i < 5; i++) { draw(g, 34 + 86 * i, 243, 36, i / 4.0, false); }
        draw(g, 493, 243, 36, 0, true);
        g.drawString("Waiting", 489, 304);
        g.drawString("Fill resets when the next tick arrives.", 270, 107);
        g.drawString("A missing tick pauses the clock.", 270, 133);
        g.dispose();
    }

    private void draw(Graphics2D g, int x, int y, int size, double progress, boolean waiting)
    {
        Graphics2D child = (Graphics2D) g.create(x, y, size, size);
        ClockFace.paint(child, size, progress, ClockFace.FILL, true, waiting);
        child.dispose();
    }

    public static void main(String[] args)
    {
        SwingUtilities.invokeLater(() -> {
            JFrame frame = new JFrame("Tick Clock - visual probe (simulated ticks)");
            frame.setDefaultCloseOperation(WindowConstants.EXIT_ON_CLOSE);
            frame.setContentPane(new ClockPreview());
            frame.pack();
            frame.setLocationRelativeTo(null);
            frame.setVisible(true);
        });
    }
}

package io.github.iamthecodedecoded.tickclock;

import org.junit.Test;
import static org.junit.Assert.*;

public class TickPhaseTest
{
    @Test public void advancesWithinTickAndResetsOnObservedTick()
    {
        TickPhase phase = new TickPhase();
        long start = 1_000_000_000L;
        assertTrue(phase.waiting(start));
        phase.tick(start);
        assertEquals(0, phase.progress(start), 0);
        assertEquals(.25, phase.progress(start + 150_000_000L), 0);
        assertEquals(.5, phase.progress(start + 300_000_000L), 0);
        assertEquals(.75, phase.progress(start + 450_000_000L), 0);
        assertEquals(1, phase.progress(start + 600_000_000L), 0);
        phase.tick(start + 605_000_000L);
        assertEquals(0, phase.progress(start + 605_000_000L), 0);
    }

    @Test public void lateTicksNeverInventCyclesAndLostSyncIsVisible()
    {
        TickPhase phase = new TickPhase();
        phase.tick(0);
        assertEquals(1, phase.progress(900_000_000L), 0);
        assertFalse(phase.waiting(900_000_000L));
        assertTrue(phase.waiting(1_300_000_000L));
        phase.tick(1_400_000_000L);
        assertFalse(phase.waiting(1_400_000_000L));
        assertEquals(0, phase.progress(1_400_000_000L), 0);
        phase.reset();
        assertTrue(phase.waiting(1_400_000_000L));
    }
}

package io.github.iamthecodedecoded.tickclock;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import org.junit.Test;
import static org.junit.Assert.*;

public class ClockFaceTest
{
    private BufferedImage render(double progress, boolean waiting)
    {
        BufferedImage image = new BufferedImage(40, 40, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        ClockFace.paint(g, 40, progress, ClockFace.FILL, false, waiting);
        g.dispose();
        return image;
    }

    private boolean blue(BufferedImage image, int x, int y)
    {
        Color color = new Color(image.getRGB(x, y), true);
        return color.getBlue() - color.getRed() > 100;
    }

    @Test public void startsAtTwelveAndFillsClockwise()
    {
        BufferedImage quarter = render(.25, false);
        assertTrue(blue(quarter, 26, 14));
        assertFalse(blue(quarter, 26, 26));
        assertFalse(blue(quarter, 14, 26));
        assertFalse(blue(quarter, 14, 14));
        BufferedImage half = render(.5, false);
        assertTrue(blue(half, 26, 26));
        assertFalse(blue(half, 14, 26));
        BufferedImage full = render(1, false);
        assertTrue(blue(full, 14, 14));
        assertFalse(blue(render(0, false), 26, 14));
    }

    @Test public void waitingClearsFillAndCornersStayTransparent()
    {
        BufferedImage waiting = render(1, true);
        assertFalse(blue(waiting, 26, 14));
        for (double progress : new double[] {0, .25, .5, .75, 1})
        {
            BufferedImage image = render(progress, false);
            assertEquals(0, image.getRGB(0, 0));
            assertEquals(0, image.getRGB(39, 39));
        }
    }
}

package io.github.iamthecodedecoded.tickclock;

import java.awt.Color;
import net.runelite.client.config.*;

@ConfigGroup("tickclock")
public interface TickClockConfig extends Config
{
    @Range(min = 24, max = 128)
    @ConfigItem(keyName = "size", name = "Clock size", description = "Diameter in pixels. Hold Alt and drag the clock to move it.", position = 0)
    default int size() { return 36; }

    @Alpha
    @ConfigItem(keyName = "fill", name = "Fill colour", description = "Clockwise fill during each tick", position = 1)
    default Color fill() { return ClockFace.FILL; }

    @ConfigItem(keyName = "hand", name = "Show clock hand", description = "Show a hand at the leading edge of the fill", position = 2)
    default boolean hand() { return true; }
}

package io.github.iamthecodedecoded.tickclock;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Arc2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Line2D;

/** Shared by the actual overlay and the packaged visual probe. */
public final class ClockFace
{
    public static final Color FILL = new Color(41, 152, 204, 230);
    private ClockFace() { }

    public static void paint(Graphics2D graphics, int size, double progress, Color fill, boolean hand, boolean waiting)
    {
        Graphics2D g = (Graphics2D) graphics.create();
        try
        {
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            double inset = 2, diameter = size - 4, center = size / 2.0;
            Ellipse2D circle = new Ellipse2D.Double(inset, inset, diameter, diameter);
            g.setColor(new Color(20, 24, 28, 205));
            g.fill(circle);
            if (!waiting)
            {
                double phase = Math.max(0, Math.min(1, progress));
                g.setColor(fill);
                g.fill(new Arc2D.Double(inset, inset, diameter, diameter, 90, -360 * phase, Arc2D.PIE));
                if (hand)
                {
                    double angle = 2 * Math.PI * phase;
                    double radius = diameter / 2 - 2;
                    g.setColor(new Color(240, 244, 247));
                    g.setStroke(new BasicStroke(1.5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
                    g.draw(new Line2D.Double(center, center, center + Math.sin(angle) * radius, center - Math.cos(angle) * radius));
                    g.fill(new Ellipse2D.Double(center - 1.5, center - 1.5, 3, 3));
                }
            }
            else
            {
                // Pause symbol makes missing tick synchronization visible without animation.
                g.setColor(new Color(232, 182, 79));
                g.setStroke(new BasicStroke(2));
                g.draw(new Line2D.Double(center - 3, center - 4, center - 3, center + 4));
                g.draw(new Line2D.Double(center + 3, center - 4, center + 3, center + 4));
            }
            g.setStroke(new BasicStroke(1));
            g.setColor(new Color(205, 221, 232, 190));
            g.draw(circle);
        }
        finally { g.dispose(); }
    }
}

package io.github.iamthecodedecoded.tickclock;

/** One observed tick; a late tick holds full instead of inventing another tick. */
final class TickPhase
{
    static final long TICK_NANOS = 600_000_000L;
    private volatile Long start;

    void tick(long now) { start = now; }
    void reset() { start = null; }

    double progress(long now)
    {
        Long observed = start;
        return observed == null ? 0 : Math.max(0, Math.min(1, (now - observed) / (double) TICK_NANOS));
    }

    boolean waiting(long now)
    {
        Long observed = start;
        return observed == null || now - observed > TICK_NANOS * 2;
    }
}

package io.github.iamthecodedecoded.tickclock;

import com.google.inject.Provides;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.*;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

@PluginDescriptor(name = "Tick Clock", description = "One clock face filling clockwise each game tick", tags = {"tick", "clock", "metronome"})
public class TickClockPlugin extends Plugin
{
    @Inject private Client client;
    @Inject private OverlayManager overlays;
    @Inject private TooltipManager tooltips;
    @Inject private TickClockConfig config;
    private final TickPhase phase = new TickPhase();
    private final Overlay clock = new TickClockOverlay();

    private final class TickClockOverlay extends Overlay
    {
        private TickClockOverlay() {
            setPosition(OverlayPosition.BOTTOM_RIGHT);
            setLayer(OverlayLayer.ABOVE_WIDGETS);
            setMovable(true);
            setResizable(false);
        }

        @Override
        public Dimension render(Graphics2D graphics)
        {
            if (client.getGameState() != GameState.LOGGED_IN) { return null; }
            long now = System.nanoTime();
            int size = Math.max(24, Math.min(128, config.size()));
            boolean waiting = phase.waiting(now);
            ClockFace.paint(graphics, size, phase.progress(now), config.fill(), config.hand(), waiting);
            if (getBounds().contains(client.getMouseCanvasPosition().getX(), client.getMouseCanvasPosition().getY()))
            {
                tooltips.add(new Tooltip(waiting ? "Waiting for game tick" : "Tick progress (600 ms estimate)"));
            }
            return new Dimension(size, size);
        }
    }

    @Provides
    TickClockConfig provideConfig(ConfigManager manager) { return manager.getConfig(TickClockConfig.class); }

    @Override
    protected void startUp() { phase.reset(); overlays.add(clock); }

    @Override
    protected void shutDown() { overlays.remove(clock); phase.reset(); }

    @Subscribe
    public void onGameTick(GameTick event) { phase.tick(System.nanoTime()); }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) { phase.reset(); }
}
